INSERT INTO "aliados" VALUES(1,'Licorera del Quindío','aliados/5eec8fd69e851d3e3a0822e503f4ecf2.png','https://ejemplo.test/licorera-quindio','Distribuidora regional de licores y destilados.','Descuento del 12 % sobre lista de precios para afiliados al día, con despacho sin costo en pedidos superiores a $800.000. Cupo de crédito a 30 días previa aprobación. Contacto comercial: convenios@ejemplo.test',1,'publicado',1,'2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "aliados" VALUES(2,'Contingentix','aliados/b723b078c11705a47163387f5a47aa0a.png','https://ejemplo.test/contingentix','Asesoría en seguridad y salud en el trabajo para el sector.','Diagnóstico SG-SST inicial sin costo para afiliados. 20 % de descuento en la implementación completa y en las capacitaciones de brigada. Incluye acompañamiento en visitas del Ministerio de Trabajo.',2,'publicado',1,'2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "aliados" VALUES(3,'Cámara de Comercio de Armenia y del Quindío','aliados/3bd7cbf6e880b2e6484417fdae79d8ed.png','https://camaraarmenia.org.co','Aliado institucional en formación empresarial y trámites de registro.',NULL,3,'publicado',1,'2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "aliados" VALUES(4,'Distribuidora Andina de Alimentos','aliados/6c45912c5c203a00ad856a48f629a0db.png','https://ejemplo.test/andina-alimentos','Insumos de cocina y abastecimiento para restaurantes bar.',NULL,4,'publicado',1,'2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "aliados" VALUES(5,'Sonido Pro Eje Cafetero','aliados/967b8e760c5bbf9ee9402349d08b1855.png','https://ejemplo.test/sonido-pro','Alquiler y mantenimiento de equipos de sonido e iluminación.',NULL,5,'publicado',1,'2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "aliados" VALUES(6,'Seguros Nocturna','aliados/3f4cac44d11982c933bfe3c269edaf69.png','https://ejemplo.test/seguros-nocturna','Pólizas de responsabilidad civil adaptadas a establecimientos nocturnos.',NULL,6,'publicado',1,'2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "artistas" VALUES(1,'DJ Marea','dj-marea','dj','House / Deep house','Sets de house melódico para terrazas y rooftops. Trae controladora propia y cabina básica. Ha tocado en Armenia, Pereira y Manizales.',450000,'https://www.youtube.com/watch?v=5qap5aO4i9A','3145511220','https://instagram.com/djmarea','artistas/ad8c5e7c4881e494823cb3e64d02e513.png',1,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,NULL,0,NULL,NULL,NULL,NULL);
INSERT INTO "artistas" VALUES(2,'DJ Kandela','dj-kandela','dj','Salsa / Tropical','Salsa brava, boogaloo y tropical de colección. Especialista en noches de salsa con público que sabe bailar.',380000,'https://youtu.be/dQw4w9WgXcQ','3106678890','https://instagram.com/djkandela','artistas/2e3a766479440b4765d73ab1056e1e03.png',1,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,NULL,0,NULL,NULL,NULL,NULL);
INSERT INTO "artistas" VALUES(3,'DJ Nocturna','dj-nocturna','dj','Techno / Minimal','Techno de closing para las últimas tres horas de la noche. Trabaja con sonido calibrado y pide prueba de sonido previa.',520000,NULL,'3122245567','https://instagram.com/djnocturna','artistas/3385111a78a2371807091f61be9e8b74.png',1,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,NULL,0,NULL,NULL,NULL,NULL);
INSERT INTO "artistas" VALUES(4,'DJ Guadua','dj-guadua','dj','Crossover / Reguetón','Crossover para público amplio: reguetón, popular y clásicos. La opción segura para un sábado lleno.',320000,NULL,'3178812204','https://instagram.com/djguadua','artistas/701356654a0e8aa95da97e2031fb8564.png',8,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,NULL,0,NULL,NULL,NULL,NULL);
INSERT INTO "artistas" VALUES(5,'Los Cafeteros del Ritmo','los-cafeteros-del-ritmo','banda','Música tropical en vivo','Orquesta de ocho músicos con repertorio de salsa, merengue y cumbia. Requieren tarima mínima de 4x3 metros y toma de 110V.',1800000,'https://www.youtube.com/watch?v=jNQXAC9IVRw','3160033218','https://instagram.com/loscafeterosdelritmo','artistas/89ef1edb297d99675c32325d8c588092.png',1,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,NULL,0,NULL,NULL,NULL,NULL);
INSERT INTO "artistas" VALUES(6,'Bahareque Rock','bahareque-rock','banda','Rock en español','Cuarteto de rock en español con covers de los noventa y material propio. Formato acústico o eléctrico según el espacio.',900000,NULL,'3134489911','https://instagram.com/baharequerock','artistas/a98bfeaf1cadb97af8ad4d2ea5d81457.png',5,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,NULL,0,NULL,NULL,NULL,NULL);
INSERT INTO "artistas" VALUES(7,'Valentina Cardona','valentina-cardona','solista','Bolero / Jazz vocal','Voz y guitarra para noches tranquilas de gastrobar. Repertorio de bolero, bossa y jazz vocal en español y portugués.',400000,NULL,'3197745503','https://instagram.com/valentinacardona','artistas/0e9957045348fcf7d39808d5233fbf0c.png',3,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,NULL,0,NULL,NULL,NULL,NULL);
INSERT INTO "artistas" VALUES(8,'Tomás Arbeláez','tomas-arbelaez','solista','Música andina colombiana','Tiple y voz, repertorio de música andina colombiana y pasillos. Muy solicitado para eventos institucionales y aperturas.',350000,NULL,'3183356674','https://instagram.com/tomasarbelaez','artistas/1c05021a0968788a0389b7a71331d676.png',2,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,NULL,0,NULL,NULL,NULL,NULL);
INSERT INTO "artistas" VALUES(9,'DJ Amanecer','dj-amanecer','dj','Afrobeat / World','Sets de cierre para el after: afrobeat, world music y downtempo. Ficha recién inscrita, todavía sin revisar.',300000,NULL,'3145511221','https://instagram.com/djamanecer','artistas/c399d91c9b0013ccc6418fd07bbbdf44.png',1,'pendiente_aprobacion','2026-08-17 22:16:21','2026-08-17 22:16:21',NULL,NULL,0,NULL,NULL,NULL,NULL);
INSERT INTO "asociados" VALUES(1,'La Cava del Yipao','la-cava-del-yipao',1,1,'Bar de barra larga y carta de destilados en el centro de Armenia. Coctelería de autor con aguardiente y café de la región, y una vitrina de vinilos que suena de jueves a sábado.','Calle 20 # 14-32, Centro','3145520114','https://instagram.com/lacavadelyipao','https://ejemplo.test/la-cava-del-yipao','https://maps.google.com/?q=La+Cava+del+Yipao+armenia','https://www.tripadvisor.co/Restaurant_Review-la-cava-del-yipao','Jue a sáb, 6:00 p. m. – 2:00 a. m.',4.53805,-75.6778,'asociados/f8e68aa858eb3ca7875e6852f8fcd2fd.png',1,'publicado','Andrés Felipe Loaiza','la-cava-del-yipao@ejemplo.test','3145520114','2026-08-17 00:00:00','Afiliado fundador. Presta el local para reuniones del capítulo.','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "asociados" VALUES(2,'Bruma Gastrobar','bruma-gastrobar',2,1,'Cocina de producto quindiano con carbón y humo. Plátano, trucha y cerdo de la región en platos para compartir, acompañados de cervezas artesanales del Eje.','Avenida Bolívar # 19-45','3106648820','https://instagram.com/brumagastrobar',NULL,'https://maps.google.com/?q=Bruma+Gastrobar+armenia','https://www.tripadvisor.co/Restaurant_Review-bruma-gastrobar','Mar a dom, 12:00 m. – 12:00 a. m.',4.53345,-75.67995,'asociados/870dc869647987bdfdd85632a76dae9c.png',1,'publicado','Daniela Restrepo Ochoa','bruma-gastrobar@ejemplo.test','3106648820','2025-05-18 00:00:00','Sin novedades.','2026-08-18 22:16:09','2026-08-18 22:16:09');
