INSERT INTO "aspirantes" VALUES(7,'Andrés Mauricio Toro','andres.toro@ejemplo.test','3197712285','Portero','seguridad','Curso de vigilancia vigente y cuatro años en control de acceso.','nuevo',1,'2026-08-10 22:16:21','2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,NULL,NULL);
INSERT INTO "beneficios" VALUES(1,'Representación gremial','Una sola voz ante la Alcaldía, la Gobernación y las Secretarías de Salud, Gobierno y Planeación. Cuando cambia una norma de horarios o de ruido, el gremio se sienta en la mesa a proponer, no a enterarse después.','heroicon-o-megaphone',1,'2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "beneficios" VALUES(2,'Descuentos en SAYCO y OSA','Tarifas preferenciales en el pago de derechos de autor y derechos conexos, negociadas por el capítulo para sus afiliados.','heroicon-o-musical-note',2,'2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "beneficios" VALUES(3,'Beneficios con aliados estratégicos','Convenios vigentes con licoreras, proveedores de tecnología y servicios para el sector. El detalle de cada convenio está disponible al iniciar sesión.','heroicon-o-gift',3,'2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "beneficios" VALUES(4,'Formación empresarial','Capacitaciones en manipulación de alimentos, servicio, costos y normatividad, dictadas con aliados y con la Cámara de Comercio de Armenia y del Quindío.','heroicon-o-academic-cap',4,'2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "beneficios" VALUES(5,'Orientación jurídica gratuita','Acompañamiento ante visitas de control, requerimientos de autoridades y trámites de apertura o renovación, sin costo para el afiliado.','heroicon-o-scale',5,'2026-08-18 22:16:06','2026-08-18 22:16:06');
