INSERT INTO "eventos" VALUES(1,'Capacitación: manipulación de alimentos para bares','capacitacion-manipulacion-de-alimentos-para-bares','capacitacion','Certificación en manipulación de alimentos dictada con la Secretaría de Salud, pensada para las cocinas pequeñas de bares y gastrobares. Cubre almacenamiento en frío, cadena de temperatura, control de plagas y el papeleo exacto que revisa el inspector cuando llega sin avisar.
INSERT INTO "eventos" VALUES(2,'ExpoBar Quindío 2026','expobar-quindio-2026','evento','La feria del sector en el Eje Cafetero: muestra comercial de proveedores, competencia de coctelería, rueda de negocios y panel de normatividad con las secretarías.
INSERT INTO "eventos" VALUES(3,'Congreso Nacional Asobares 2026','congreso-nacional-asobares-2026','evento','El encuentro anual de la Asociación de Bares de Colombia. El capítulo Quindío asiste con delegación propia. La inscripción se gestiona directamente en la plataforma de la Nacional.','Cartagena de Indias','2026-11-06 09:00:00','2026-11-08 18:00:00','eventos/735df517cf625b48fdb26a3e71c6d8d2.png',NULL,0,0,'https://asobares.org/congreso-nacional','publicado','2026-08-18 22:16:21','2026-08-18 22:16:21');
INSERT INTO "eventos" VALUES(4,'Mercado Nocturno — segunda edición','mercado-nocturno-segunda-edicion','evento','Mercado campesino sobre la Avenida Bolívar, dentro de la línea de Cultura del capítulo. Música en vivo, rincón cultural, exposición de bares, stand de bebidas y muestra de licoreras.
INSERT INTO "eventos" VALUES(5,'Socialización del Sello Púrpura','socializacion-del-sello-purpura','capacitacion','Presentación de la estrategia del Sello Púrpura a los equipos de los establecimientos afiliados, dentro de la línea de Seguridad del capítulo.
INSERT INTO "eventos" VALUES(6,'Lanzamiento del Observatorio Económico Nocturno','lanzamiento-del-observatorio-economico-nocturno','evento','Presentación pública de las primeras cifras del Observatorio: participación de la economía nocturna en el empleo de Armenia, ingresos medios del sector e informalidad.','Cámara de Comercio de Armenia y del Quindío','2026-04-20 09:00:00','2026-04-20 11:30:00','eventos/1ba415beeb5f73786f78df5236338f28.png',120,0,0,NULL,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21');
INSERT INTO "iniciativas" VALUES(1,'Vibrarte','vibrarte','Corredor peatonal seguro e iluminado, activo 24 horas.','Un corredor sobre la carrera 14 pensado como proyecto de ciudad: señalización, iluminación y presencia institucional para que la gente camine tranquila a cualquier hora. Es el primer distrito de experiencia del departamento y el modelo que el gremio quiere replicar en otros municipios.','en_ejecucion','Cultura','Carrera 14, Armenia',1,'publicado','2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "iniciativas" VALUES(2,'Bares Verdes','bares-verdes','Certificación en sostenibilidad y responsabilidad social.','Acompañamiento para que los establecimientos reduzcan su huella ambiental: separación de residuos, eficiencia energética y compra a productores locales. Quien cumple los criterios recibe la certificación del gremio.','en_ejecucion','Sostenibilidad',NULL,2,'publicado','2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "iniciativas" VALUES(3,'Blindando tu Negocio','blindando-tu-negocio','Seguridad y revisión constante en los establecimientos.','Revisión periódica de las condiciones de seguridad de cada local —extintores, salidas, instalación eléctrica, control de acceso— antes de que llegue una visita de control. La idea es simple: que el inspector no encuentre nada que el gremio no haya revisado primero.','escalando','Seguridad',NULL,3,'publicado','2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "iniciativas" VALUES(4,'Noche Segura y Competitiva','noche-segura-y-competitiva','Brigadas de emergencia y profesionalización del personal.','Conformación de brigadas de emergencia y formación del personal de servicio y seguridad, arrancando por Circasia y Calarcá. Busca que los municipios pequeños tengan el mismo estándar de operación que Armenia.','formulacion','Seguridad','Circasia y Calarcá',4,'publicado','2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "iniciativas" VALUES(5,'Diplomado en Gerencia de Bares','diplomado-en-gerencia-de-bares','Formación gerencial formal para empresarios del sector.','Un programa formal para que el dueño de establecimiento deje de aprender a los golpes: costos, normatividad, manejo de personal y planeación. Pensado para el dueño pequeño, que suele ser también el bartender y el administrador.','formulacion','Cultura',NULL,5,'publicado','2026-08-18 22:16:06','2026-08-18 22:16:06');
