INSERT INTO "mensajes" VALUES(1,'afiliacion','Sandra Milena Ríos','sandra.rios@ejemplo.test','3145523311','Buenas tardes. Tengo un gastrobar en el centro de Armenia, llevamos ocho meses abiertos y quisiera saber cómo afiliarme al gremio y qué requisitos piden.',1,'2026-08-03 22:16:21',NULL,'nuevo',NULL,NULL,'2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,NULL,NULL);
INSERT INTO "mensajes" VALUES(2,'afiliacion','Jorge Enrique Patiño','jorge.patino@ejemplo.test','3106645002','Estoy montando un bar en Calarcá y me recomendaron afiliarme antes de abrir para que me orienten con los permisos. ¿Es posible?',1,'2026-08-12 22:16:21',NULL,'en_tramite',NULL,NULL,'2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,NULL,NULL);
INSERT INTO "mensajes" VALUES(3,'pqr','Carlos Alberto Muñoz','carlos.munoz@ejemplo.test','3122234780','Pago mi mensualidad hace cuatro meses y aún no me llega el carné de afiliado que da acceso al descuento de Sayco. Necesito saber en qué va el trámite.',1,'2026-07-23 22:16:21','PQR-2026-0001','respondido','Se verificó el pago y se despachó el carné el 18 del mes pasado. Se envió guía de seguimiento al correo del afiliado.','2026-08-12 22:16:21','2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,NULL,NULL);
INSERT INTO "mensajes" VALUES(4,'pqr','Liliana Andrea Vargas','liliana.vargas@ejemplo.test','3178856640','La capacitación de costos del mes pasado se canceló el mismo día y nadie avisó. Perdí un turno de trabajo por asistir. Solicito que se comunique con más anticipación.',1,'2026-08-03 22:16:21','PQR-2026-0002','en_tramite',NULL,NULL,'2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,NULL,NULL);
INSERT INTO "mensajes" VALUES(5,'pqr','Ómar Yesid Grajales','omar.grajales@ejemplo.test','3160012298','Quiero saber por qué el certificado de bomberos en Salento cuesta distinto al de Armenia. ¿El gremio puede gestionar una tarifa unificada?',1,'2026-08-11 22:16:21','PQR-2026-0003','nuevo',NULL,NULL,'2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,NULL,NULL);
INSERT INTO "mensajes" VALUES(6,'proveedor','Distribuidora El Congelador','ventas@elcongelador.test','3134470012','Somos distribuidores de hielo en Quimbaya y Montenegro. Queremos aparecer en la bolsa de proveedores. ¿Cuál es el costo y qué se necesita?',1,'2026-07-21 22:16:21',NULL,'nuevo',NULL,NULL,'2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,NULL,NULL);
INSERT INTO "mensajes" VALUES(7,'proveedor','Mantenimiento Industrial GT','contacto@mantenimientogt.test','3197723345','Prestamos servicio de mantenimiento de campanas de extracción y cuartos fríos con disponibilidad de fin de semana. Nos interesa entrar a la base de proveedores del gremio.',1,'2026-08-05 22:16:21',NULL,'en_tramite',NULL,NULL,'2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,NULL,NULL);
INSERT INTO "mensajes" VALUES(8,'aliado','Seguros Andinos S.A.','alianzas@segurosandinos.test','3183390077','Queremos proponer un convenio de pólizas de responsabilidad civil para los afiliados del capítulo. ¿Con quién podemos agendar una presentación?',1,'2026-07-31 22:16:21',NULL,'nuevo',NULL,NULL,'2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,NULL,NULL);
INSERT INTO "mensajes" VALUES(9,'contacto','Paula Restrepo Hoyos','paula.restrepo@ejemplo.test','3115560089','Soy estudiante de Administración de Turismo y estoy haciendo mi trabajo de grado sobre economía nocturna. ¿Pueden compartirme las cifras del Observatorio?',1,'2026-07-23 22:16:21',NULL,'respondido','Se compartió el boletín del Observatorio y se remitió a la sección pública del sitio.','2026-08-15 22:16:21','2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,NULL,NULL);
