INSERT INTO "proveedores" VALUES(1,'Hielo Cristal del Quindío','hielo-cristal-del-quindio','hielo','Hielo en cubo, escarcha y barra. Reparto diario en Armenia y municipios cercanos, con entregas de refuerzo los viernes y sábados.','3145560012','ventas@hielocristal.test',1,'2027-02-18 00:00:00','publicado','2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,0,NULL,NULL,NULL,NULL);
