INSERT INTO "requisitos_apertura" VALUES(1,1,'Cámara de Comercio de Armenia y del Quindío','La matrícula mercantil es el primer paso: sin ella no puedes tramitar nada más. Se renueva cada año antes del 31 de marzo.','["Formulario RUES diligenciado (persona natural o jur\u00eddica)","C\u00e9dula del propietario o del representante legal","RUT expedido por la DIAN","Consulta previa de homonimia del nombre comercial","Pago del derecho de matr\u00edcula seg\u00fan los activos declarados"]','https://camaraarmenia.org.co',NULL,NULL,180000,1,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21');
INSERT INTO "requisitos_apertura" VALUES(2,1,'Alcaldía de Armenia — Uso de suelos','El certificado de uso de suelos dice si en esa dirección se puede operar un establecimiento nocturno. Consúltalo ANTES de firmar el arriendo: es el error más caro y más común.','["Solicitud de concepto de uso de suelo por direcci\u00f3n exacta","Certificado de matr\u00edcula mercantil","Croquis de ubicaci\u00f3n del inmueble","Verificar la distancia m\u00ednima a colegios e iglesias"]','https://armenia.gov.co',NULL,NULL,45000,2,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21');
INSERT INTO "requisitos_apertura" VALUES(3,1,'Cuerpo de Bomberos de Armenia','Concepto técnico de seguridad humana. Revisan extintores, señalización, salidas de emergencia y la instalación eléctrica. Descarga el formato, diligéncialo y radícalo para que agenden la visita.','["Carta de solicitud de visita t\u00e9cnica diligenciada","Extintores vigentes y con recarga certificada","Se\u00f1alizaci\u00f3n de rutas de evacuaci\u00f3n y salidas","Botiqu\u00edn de primeros auxilios dotado","Certificado de mantenimiento de la instalaci\u00f3n el\u00e9ctrica","Plan de emergencia y contingencia del establecimiento"]',NULL,'formatos/formato-solicitud-visita-bomberos.pdf','Formato de solicitud de visita — Bomberos Armenia',120000,3,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21');
INSERT INTO "requisitos_apertura" VALUES(4,1,'Sayco y Acinpro','Si suena música en tu establecimiento, causa derechos de autor y derechos conexos. Los afiliados a ASOBARES tienen tarifa preferencial negociada por el gremio.','["Formulario de declaraci\u00f3n del establecimiento","Indicar \u00e1rea del local y aforo real","Declarar el tipo de m\u00fasica y si hay ejecuci\u00f3n en vivo","Presentar el carn\u00e9 de afiliaci\u00f3n a ASOBARES para el descuento"]','https://www.sayco.org',NULL,NULL,380000,4,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21');
INSERT INTO "requisitos_apertura" VALUES(5,1,'Secretaría de Salud de Armenia','Concepto sanitario favorable. Obligatorio si manipulas alimentos o bebidas, es decir: prácticamente siempre.','["Certificados de manipulaci\u00f3n de alimentos de todo el personal","Concepto sanitario del establecimiento","Contrato vigente de control de plagas","Certificado de lavado y desinfecci\u00f3n de tanques de agua","Plan de manejo de residuos s\u00f3lidos"]',NULL,NULL,NULL,NULL,5,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21');
INSERT INTO "requisitos_apertura" VALUES(6,1,'Policía Nacional — Control de horarios','Registro del establecimiento y verificación del horario autorizado. Es la entidad que más visita de noche: ten los papeles a la mano y visibles.','["Formato de registro del establecimiento diligenciado","Aviso visible de prohibici\u00f3n de ingreso a menores de edad","Horario autorizado exhibido en la entrada","Documentos de funcionamiento disponibles en el local","Personal de seguridad debidamente identificado"]',NULL,'formatos/formato-registro-policia.pdf','Formato de registro de establecimiento — Policía',NULL,6,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21');
INSERT INTO "requisitos_apertura" VALUES(7,2,'Cámara de Comercio de Armenia y del Quindío','Salento se atiende desde la seccional de Armenia. Mismo trámite de matrícula mercantil, con atención presencial los martes en el municipio.','["Formulario RUES diligenciado","C\u00e9dula del propietario o representante legal","RUT expedido por la DIAN","Consulta previa de homonimia del nombre comercial"]','https://camaraarmenia.org.co',NULL,NULL,180000,1,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21');
INSERT INTO "requisitos_apertura" VALUES(8,2,'Alcaldía de Salento — Uso de suelos','Salento es Paisaje Cultural Cafetero: el centro histórico tiene restricciones adicionales de fachada, aviso y niveles de ruido que no aplican en otros municipios.','["Solicitud de concepto de uso de suelo","Concepto de la oficina de Planeaci\u00f3n sobre intervenci\u00f3n de fachada","Aprobaci\u00f3n del dise\u00f1o del aviso comercial","Verificar restricci\u00f3n de ruido en el per\u00edmetro del centro hist\u00f3rico"]',NULL,NULL,NULL,38000,2,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21');
INSERT INTO "requisitos_apertura" VALUES(9,2,'Cuerpo de Bomberos de Salento','En Salento el concepto de bomberos cuesta cerca de $100.000 y la visita se agenda con menos frecuencia: solicítala con tiempo.','["Carta de solicitud de visita t\u00e9cnica","Extintores vigentes con recarga certificada","Se\u00f1alizaci\u00f3n de evacuaci\u00f3n","Certificado de la instalaci\u00f3n el\u00e9ctrica","Consideraciones especiales para construcciones en bahareque y madera"]',NULL,'formatos/formato-solicitud-visita-bomberos.pdf','Formato de solicitud de visita — Bomberos Salento',100000,3,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21');
INSERT INTO "requisitos_apertura" VALUES(10,2,'Sayco y Acinpro','Tarifa nacional según área y aforo, con descuento para afiliados al gremio.','["Formulario de declaraci\u00f3n del establecimiento","\u00c1rea del local y aforo real","Declarar si hay m\u00fasica en vivo","Carn\u00e9 de afiliaci\u00f3n a ASOBARES para el descuento"]','https://www.sayco.org',NULL,NULL,290000,4,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21');
INSERT INTO "requisitos_apertura" VALUES(11,2,'Secretaría de Salud del Quindío','En municipios sin secretaría propia, el concepto sanitario lo emite la Secretaría departamental.','["Certificados de manipulaci\u00f3n de alimentos del personal","Concepto sanitario del establecimiento","Control de plagas vigente","Certificado de potabilidad del agua"]',NULL,NULL,NULL,NULL,5,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21');
INSERT INTO "requisitos_apertura" VALUES(12,2,'Policía Nacional — Control de horarios','El horario en Salento es más restrictivo que en Armenia por la vocación turística del municipio. Confirma el horario vigente antes de programar tu operación.','["Formato de registro del establecimiento","Aviso de prohibici\u00f3n de ingreso a menores","Horario autorizado exhibido en la entrada","Documentos de funcionamiento en el local"]',NULL,'formatos/formato-registro-policia.pdf','Formato de registro de establecimiento — Policía',NULL,6,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21');
INSERT INTO "requisitos_apertura" VALUES(13,3,'Cámara de Comercio de Armenia y del Quindío','Matrícula mercantil para Filandia, tramitada en la seccional de Armenia o en las jornadas móviles del municipio.','["Formulario RUES diligenciado","C\u00e9dula del propietario o representante legal","RUT expedido por la DIAN","Consulta de homonimia"]','https://camaraarmenia.org.co',NULL,NULL,180000,1,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21');
INSERT INTO "requisitos_apertura" VALUES(14,3,'Alcaldía de Filandia — Uso de suelos','El centro histórico de Filandia también está protegido. Los balcones y fachadas tienen norma propia y el aviso comercial requiere aprobación.','["Solicitud de concepto de uso de suelo","Aprobaci\u00f3n de intervenci\u00f3n de fachada si aplica","Dise\u00f1o del aviso comercial aprobado por Planeaci\u00f3n","Verificaci\u00f3n de aforo permitido para el inmueble"]',NULL,NULL,NULL,35000,2,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21');
INSERT INTO "requisitos_apertura" VALUES(15,3,'Cuerpo de Bomberos de Filandia','Concepto técnico de seguridad humana, con énfasis en las construcciones tradicionales de madera del centro.','["Carta de solicitud de visita t\u00e9cnica","Extintores vigentes","Se\u00f1alizaci\u00f3n de evacuaci\u00f3n","Certificado el\u00e9ctrico","Medidas reforzadas para inmuebles en madera"]',NULL,'formatos/formato-solicitud-visita-bomberos.pdf','Formato de solicitud de visita — Bomberos Filandia',95000,3,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21');
INSERT INTO "requisitos_apertura" VALUES(16,3,'Sayco y Acinpro','Declaración y pago de derechos de autor y conexos según área y aforo.','["Formulario de declaraci\u00f3n","\u00c1rea y aforo del establecimiento","Declarar m\u00fasica en vivo si aplica","Carn\u00e9 de afiliaci\u00f3n a ASOBARES"]','https://www.sayco.org',NULL,NULL,270000,4,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21');
INSERT INTO "requisitos_apertura" VALUES(17,3,'Secretaría de Salud del Quindío','Concepto sanitario emitido por la Secretaría departamental.','["Certificados de manipulaci\u00f3n de alimentos","Concepto sanitario","Control de plagas vigente","Manejo de residuos s\u00f3lidos"]',NULL,NULL,NULL,NULL,5,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21');
INSERT INTO "requisitos_apertura" VALUES(18,3,'Policía Nacional — Control de horarios','Registro y verificación de horarios. Filandia aplica restricciones especiales en temporada alta y festivos.','["Formato de registro del establecimiento","Aviso de prohibici\u00f3n de ingreso a menores","Horario autorizado visible","Documentos de funcionamiento en el local"]',NULL,'formatos/formato-registro-policia.pdf','Formato de registro de establecimiento — Policía',NULL,6,'publicado','2026-08-18 22:16:21','2026-08-18 22:16:21');
