INSERT INTO "settings" VALUES(1,'sitio_nombre','ASOBARES Capítulo Quindío','string','identidad','Nombre del sitio','2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "settings" VALUES(2,'sitio_eslogan','La noche construye territorio','string','identidad','Lema del capítulo','2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "settings" VALUES(3,'sitio_descripcion_corta','El gremio que representa, fortalece y dinamiza el sector nocturno, gastronómico y de entretenimiento del Quindío.','string','identidad','Descripción corta','2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "settings" VALUES(4,'sitio_descripcion','Asociación de Bares de Colombia, Capítulo Quindío. Representamos a bares, gastrobares, cafés y discotecas del departamento ante las instituciones, y acompañamos a quien quiere abrir su establecimiento.','text','identidad','Descripción para buscadores','2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "settings" VALUES(5,'hero_titulo','La noche construye territorio','string','inicio','Título del hero','2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "settings" VALUES(6,'hero_subtitulo','Somos el gremio que se sienta en la mesa con las instituciones y el que te explica, paso a paso, cómo abrir tu establecimiento sin que te lo cierren. Trabajamos por la dignificación de la vida nocturna del Quindío.','text','inicio','Subtítulo del hero','2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "settings" VALUES(7,'hero_cta_directorio','Explora la noche','string','inicio','Botón hacia el directorio','2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "settings" VALUES(8,'hero_cta_afiliate','Afíliate','string','inicio','Botón hacia afiliación','2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "settings" VALUES(9,'cta_final_titulo','¿Tu establecimiento todavía no es parte del gremio?','string','inicio','Título del cierre','2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "settings" VALUES(10,'cta_final_texto','Afiliarte toma una conversación. Representación ante las instituciones, descuentos en derechos de autor, formación y orientación jurídica sin costo.','text','inicio','Texto del cierre','2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "settings" VALUES(11,'manifiesto_apertura','Nos conocen por la rumba. Pero hoy venimos a hablarles del territorio.','string','manifiesto','Frase de apertura','2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "settings" VALUES(12,'manifiesto_cierre_titulo','Asobares no representa bares. Representa el Quindío que se vive de noche.','string','manifiesto','Frase de cierre','2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "settings" VALUES(13,'manifiesto_cierre_firma','Construyendo un Quindío nocturno','string','manifiesto','Firma del cierre','2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "settings" VALUES(14,'vision_titulo','En 10 años, el Quindío no tendrá bares. Tendrá momentos memorables.','string','manifiesto','Visión a 10 años','2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "settings" VALUES(15,'vision_nota','No solo tragos: una experiencia.','string','manifiesto','Nota al margen de la visión','2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "settings" VALUES(16,'vision_detalle','Cada municipio, un distrito de experiencia — con señalización, iluminación y seguridad como proyecto de ciudad.
INSERT INTO "settings" VALUES(17,'barreras','La informalidad nos compite en la calle | El consumo y la venta informal en el espacio público erosionan la competencia leal y deterioran la imagen del sector formal.
INSERT INTO "settings" VALUES(18,'iniciativas_titulo','Las iniciativas más importantes','string','manifiesto','Título de iniciativas','2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "settings" VALUES(19,'iniciativas_intro','Lo que el gremio ya tiene en marcha para cumplir ese sueño.','string','manifiesto','Introducción de iniciativas','2026-08-18 22:16:06','2026-08-18 22:16:06');
INSERT INTO "settings" VALUES(20,'cifra_empleo','12,65 %','string','cifras','Participación en el empleo de Armenia','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(21,'cifra_empleo_detalle','del empleo de Armenia lo genera la economía nocturna','string','cifras','Detalle de la cifra de empleo','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(22,'cifra_ingreso','$2.104.124','string','cifras','Ingreso medio mensual del sector','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(23,'cifra_ingreso_detalle','es el ingreso medio mensual en el sector','string','cifras','Detalle del ingreso','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(24,'cifra_informalidad','72,82 %','string','cifras','Informalidad','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(25,'cifra_informalidad_detalle','de informalidad: el reto que el gremio quiere cerrar','string','cifras','Detalle de informalidad','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(26,'cifra_jovenes','35,28 %','string','cifras','Trabajadores de 28 años o menos','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(27,'cifra_jovenes_detalle','de los trabajadores tiene 28 años o menos','string','cifras','Detalle de juventud','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(28,'cifra_afiliados','60','string','cifras','Establecimientos afiliados','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(29,'quienes_historia','Somos una organización gremial que nace en Bogotá y llega al Quindío con la necesidad de afianzar la relación TURISMO – NOCHE. El capítulo se fundó el 14 de agosto de 2024 en Armenia y reúne a bares, gastrobares, cafés y discotecas del departamento alrededor de una idea simple: la vida nocturna es una industria que genera empleo, paga impuestos y merece ser tratada como tal.','text','institucional','Historia','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(30,'quienes_mision','Representar al sector de la vida nocturna del Quindío ante las instituciones públicas y privadas, para proponer como gremio: participar en las decisiones sobre horarios, ruido, orden público y formalización antes de que se tomen, y no reclamar después.','text','institucional','Misión','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(31,'quienes_que_hacemos','Trabajamos por una vida nocturna más diversa y por la dignificación del sector, para consolidarnos como el corazón nocturno del Eje Cafetero. Gestionamos con las Secretarías de Salud, Gobierno y Planeación; negociamos tarifas de derechos de autor; formamos a los equipos de nuestros afiliados; y construimos la guía normativa por municipio que hoy no tiene ningún otro gremio del país.','text','institucional','Qué hacemos','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(32,'quienes_vision','Hacia la transformación del Quindío en un paraíso nocturno seguro','string','institucional','Visión','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(33,'quienes_presidente','Jorge Iván Botero Ángel','string','institucional','Presidente','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(34,'quienes_directora','Natalia Gutiérrez','string','institucional','Directora ejecutiva','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(35,'quienes_fundacion','14 de agosto de 2024','string','institucional','Fecha de fundación','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(36,'quienes_lineas','Seguridad | Promover esparcimiento seguro en el Quindío, articulados con las secretarías de gobierno de cada municipio. En 2024, el 73 % de los visitantes del departamento decidió hospedarse aquí: la seguridad y la convivencia son parte del atractivo turístico. | Sello Púrpura; Sello Seguro; Campañas de socialización
INSERT INTO "settings" VALUES(37,'quienes_estrategia_armenia','Armenia Nocturna es la propuesta del capítulo para la ciudad: articular a la Secretaría de Gobierno y a la de Desarrollo Económico alrededor de una vida económica nocturna regulada, segura y reconocida como industria.','text','institucional','Estrategia Armenia Nocturna','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(38,'quienes_programas_nacionales','Tardeo en la ciudad
