INSERT INTO "settings" VALUES(44,'contacto_direccion','Piso 3, Cámara de Comercio de Armenia y del Quindío','string','contacto','Dirección','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(45,'contacto_ciudad','Armenia, Quindío','string','contacto','Ciudad','2026-08-18 22:16:07','2026-08-18 22:16:07');
