INSERT INTO "settings" VALUES(48,'contacto_correo_destino','asobaresquindio@asobares.org','string','contacto','Correo que recibe los formularios','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(49,'guia_titulo','Abre tu negocio sin que te lo cierren','string','guia','Título de la guía','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(50,'guia_intro','La normatividad cambia de un municipio a otro. Escoge el tuyo y revisa, entidad por entidad, qué te van a pedir, cuánto cuesta y qué formato tienes que descargar y llevar diligenciado.','text','guia','Introducción de la guía','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(51,'guia_descargo','Esta guía es orientativa y se actualiza con la información que cada entidad entrega al gremio. Los requisitos, costos y formatos pueden cambiar sin aviso: verifica siempre directamente con la entidad competente antes de iniciar tu trámite.','text','guia','Texto de descargo','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(52,'empleo_titulo','Bolsa de empleo del sector','string','empleo','Título','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(53,'empleo_intro','Bartenders, chefs, meseros y administradores para la vida nocturna del Quindío. Conseguir un buen bartender acá es lo más difícil; por eso el muro existe.','text','empleo','Introducción','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(54,'empleo_aviso','Solo los establecimientos asociados publican vacantes en este muro.','string','empleo','Aviso del muro','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(55,'artistas_titulo','Directorio de artistas','string','modulos','Título de artistas','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(56,'artistas_intro','DJs, bandas y solistas de la región. Son las once de la noche, se te cayó el DJ y necesitas uno: aquí está su género, su tarifa desde, su contacto y un video para escucharlo antes de llamar.','text','modulos','Introducción de artistas','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(57,'proveedores_titulo','Bolsa de proveedores','string','modulos','Título de proveedores','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(58,'proveedores_intro','Hielo, licores, alimentos, aseo, seguridad y mantenimiento. ¿Quién te arregla la campana de extracción un sábado? Aquí.','text','modulos','Introducción de proveedores','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(59,'boletin_titulo','Boletín del gremio','string','boletin','Título del boletín','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(60,'boletin_intro','Publicamos poco y publicamos cuando hay algo que decir: cifras del Observatorio Económico que envía la Nacional, decisiones que afectan al sector y los proyectos en los que está trabajando el capítulo.','text','boletin','Introducción del boletín','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(61,'afiliate_titulo','Afíliate al gremio','string','afiliacion','Título','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(62,'afiliate_intro','Tu establecimiento deja de estar solo frente a una visita de control, una norma nueva o una tarifa de derechos de autor. Déjanos tus datos y te contactamos.','text','afiliacion','Introducción','2026-08-18 22:16:07','2026-08-18 22:16:07');
INSERT INTO "settings" VALUES(63,'afiliate_como_funciona','Nos escribes por el formulario o por WhatsApp.
INSERT INTO "settings" VALUES(64,'politica_responsable','Asociación de Bares de Colombia — Capítulo Quindío','string','legal','Responsable del tratamiento','2026-08-18 22:16:07','2026-08-18 22:16:07');
