INSERT INTO "vacantes" VALUES(1,9,'Bartender','por_turnos','Buscamos bartender con mínimo un año de experiencia en barra de alto volumen. Debe manejar coctelería clásica, control de inventario de barra y trabajo bajo presión en noches de lleno total. Se paga por turno más propinas repartidas.','Viernes y sábados, 8:00 p. m. – 4:00 a. m.','3151189203','publicado','2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,NULL,NULL,'barra');
INSERT INTO "vacantes" VALUES(2,2,'Chef de cocina','tiempo_completo','Chef para liderar la cocina: diseño de carta de temporada con producto quindiano, manejo de costos, escandallos y equipo de cuatro personas. Indispensable certificado de manipulación de alimentos vigente.','Martes a domingo, 10:00 a. m. – 8:00 p. m.','3106648820','publicado','2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,NULL,NULL,'cocina');
INSERT INTO "vacantes" VALUES(3,4,'Mesero','por_turnos','Mesero para servicio de terraza. Buena presentación, manejo de bandeja y toma de pedido en tableta. No se requiere experiencia previa: capacitamos. Ideal para estudiantes.','Miércoles a sábado, 5:00 p. m. – 1:00 a. m.','3178834502','publicado','2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,NULL,NULL,'servicio');
INSERT INTO "vacantes" VALUES(4,1,'Administrador de establecimiento','tiempo_completo','Administrador con experiencia en el sector nocturno: manejo de personal, cuadre de caja, relación con proveedores y cumplimiento de la normatividad (bomberos, salud, Sayco). Se valora conocimiento de software de punto de venta.','Lunes a sábado, horario administrativo con noches de cierre','3145520114','publicado','2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,NULL,NULL,'administracion');
INSERT INTO "vacantes" VALUES(5,5,'Portero / control de acceso','por_turnos','Personal para control de acceso y requisa en puerta. Debe tener curso de vigilancia vigente y manejo de situaciones de conflicto sin escalarlas. Trabajo en dupla.','Viernes y sábados, 9:00 p. m. – 3:00 a. m.','3160074455','publicado','2026-08-18 22:16:21','2026-08-18 22:16:21',NULL,NULL,NULL,'seguridad');
INSERT INTO "vacantes" VALUES(6,2,'Auxiliar de cocina','tiempo_completo','Apoyo en preparación de mise en place, montaje de platos y aseo de cocina. Se requiere certificado de manipulación de alimentos. Vacante todavía en revisión de la dirección.','Martes a domingo, 11:00 a. m. – 7:00 p. m.','3106648820','pendiente_aprobacion','2026-08-16 22:16:21','2026-08-16 22:16:21',NULL,NULL,NULL,'cocina');
INSERT INTO "vacantes" VALUES(7,5,'Bartender para noche de aniversario','momentaneo','Refuerzo de barra para una sola noche: aniversario del club con aforo lleno. Se paga el turno completo esa misma noche.','Sábado, 8:00 p. m. – 4:00 a. m.','3160074455','publicado','2026-08-18 22:16:21','2026-08-18 22:16:21','2026-09-01 00:00:00',NULL,NULL,'barra');
